function generate_digest(val: uint64, reg_type: enum {INT, FP, FLAG}) -> uint12:
    if reg_type == INT:
        // 6 LSBs of the 64-bit value
        val_lsb = val & 0x3F
        // Count identical trailing bits matching bit 0 (or trailing zeros/ones, capped at 63)
        trailing = count_trailing_zeros(val) if (val & 1) == 0 else count_trailing_ones(val)
        trailing_cnt = min(trailing, 63) & 0x3F
        // Count identical leading bits matching bit 63 (or leading zeros/ones, capped at 63)
        leading = count_leading_zeros(val) if ((val >> 63) & 1) == 0 else count_leading_ones(val)
        leading_cnt = min(leading, 63) & 0x3F
        // Overlapping XOR fold per Figure 6(a)
        return (trailing_cnt & 0x3F) ^ ((leading_cnt & 0x3F) << 3) ^ ((val_lsb & 0x3F) << 6)
    else if reg_type == FP:
        // Inspect MSBs to identify floating-point width/format
        // Per Figure 6(b), right-aligned at digest bit 3
        if is_fp16(val):
            // Val[15:13]: sign bit and top 2 exponent bits
            return ((val >> 13) & 0x07) << 3
        else if is_fp32(val):
            // Val[31:26]: sign bit and top 5 exponent bits
            return ((val >> 26) & 0x3F) << 3
        else: // FP64
            // Val[63:55]: sign bit and top 8 exponent bits
            return ((val >> 55) & 0x1FF) << 3
    else: // FLAG
        // Replicate the 4 condition-code flag bits 3 times
        flags = val & 0x0F
        return (flags << 8) | (flags << 4) | flags

function on_instruction_decode(inst):
    for dest_reg in inst.destination_registers:
        if dest_reg < 65:
            RTT[dest_reg].valid = 0
            RTT[dest_reg].payload = inst.rob_tag & 0x3FFF // store 14-bit ROB tag
            RTT[dest_reg].decay_ctr = 0

function on_instruction_complete(rob_tag: uint14, dest_reg: int, result_val: uint64, reg_type: enum):
    if dest_reg < 65:
        // Confirm ROB tag matches current in-flight reservation
        if RTT[dest_reg].valid == 0 and RTT[dest_reg].payload == (rob_tag & 0x3FFF):
            RTT[dest_reg].payload = generate_digest(result_val, reg_type) & 0x0FFF
            RTT[dest_reg].valid = 1
            RTT[dest_reg].decay_ctr = 255 // reset 256-instruction decay window

function on_decode_cycle_tick():
    for r from 0 to 64:
        if RTT[r].valid == 1:
            if RTT[r].decay_ctr > 0:
                RTT[r].decay_ctr = RTT[r].decay_ctr - 1
            if RTT[r].decay_ctr == 0:
                RTT[r].valid = 0

function lookup_sr(pc: uint64) -> int:
    sR = 0
    for bank from 0 to 7:
        regs_in_bank = [r for r in 0..64 if (r % 8) == bank]
        // Check which registers in this bank have valid digests
        valid_regs = [r for r in regs_in_bank if RTT[r].valid == 1]
        if valid_regs is empty:
            continue // Bank contribution is 0

        // Compute usefulness vector for registers in this bank
        // UT index hashed per table
        idx_ut0 = hash(pc, 0, bank) % 8
        idx_ut1 = hash(pc, 1, bank) % 8
        idx_ut2 = hash(pc, 2, bank) % 8

        best_reg = valid_regs[0]
        best_usefulness = -9999
        for r in valid_regs:
            reg_pos = r // 8 // relative offset in bank entry
            u = UT0[bank][idx_ut0].weights[reg_pos] + \
                UT1[bank][idx_ut1].weights[reg_pos] + \
                UT2[bank][idx_ut2].weights[reg_pos]
            if u > best_usefulness:
                best_usefulness = u
                best_reg = r

        // Digest side: hash selected register's digest with PC
        digest = RTT[best_reg].payload & 0x0FFF
        idx_wt0 = hash(pc, digest, 0, bank) % 512
        idx_wt1 = hash(pc, digest, 1, bank) % 256
        idx_wt2 = hash(pc, digest, 2, bank) % 128

        bank_sum = WT0[bank][idx_wt0] + WT1[bank][idx_wt1] + WT2[bank][idx_wt2]

        // Apply multiplier (x2.5 if useful, x0 if not)
        if best_usefulness > 0:
            scaled_bank_sum = int(bank_sum * 2.5)
        else:
            scaled_bank_sum = 0
        sR = sR + scaled_bank_sum

    return sR

function recover_on_squash(flushed_rob_tags: set of uint14):
    for r from 0 to 64:
        if RTT[r].valid == 0 and (RTT[r].payload in flushed_rob_tags):
            // Clear speculative pending write
            RTT[r].payload = 0
            RTT[r].decay_ctr = 0
